#include <iostream>
#include <type_traits>
template <int N> struct Factorial {
  static constexpr int value = N * Factorial<N - 1>::value;
};
template <> struct Factorial<0> {
  static constexpr int value = 1;
};
template <int N> struct Fibonacci {
  static constexpr int value = Fibonacci<N - 1>::value + Fibonacci<N - 2>::value;
};
template <> struct Fibonacci<0> {
  static constexpr int value = 0;
};
template <> struct Fibonacci<1> {
  static constexpr int value = 1;
};
int main() {
  constexpr int fact5 = Factorial<5>::value;  // Computed at compile time
  constexpr int fib8 = Fibonacci<8>::value;   // Computed at compile time
  static_assert(fact5 == 120, "Factorial calculation is incorrect");
  std::cout << "Factorial of 5: " << fact5 << std::endl;
  std::cout << "Fibonacci of 8: " << fib8 << std::endl;
  return 0;
}
